#include <vector>
#include <algorithm>

using namespace std;

class collision_geometry
{
public:
  virtual bool is_camera_collision() const { return false; }
};

class entity
{
  char before_ext_flags[0x174];
  unsigned int ext_flags;
public:
  bool is_scannable() const { return((ext_flags & 0x00000020)); }
  bool is_beamable() const { return((ext_flags & 0x00000040)); }
  virtual collision_geometry * get_colgeom() const;
};

class region
{
public:
  typedef vector<entity*> entity_list;
  void remove( entity* e );
  void remove_cam_coll_ent( entity* e );

private:
  char before_entities[0x24];
  entity_list entities;
  entity_list cam_coll_ents;
  entity_list possible_active_ents;
  entity_list possible_render_ents;
  entity_list possible_collide_ents;
};

void region::remove( entity* e )
{
  entity_list::iterator ei_end = entities.end();
  entity_list::iterator ei = find( entities.begin(), ei_end, e );
  if ( ei != ei_end )
  {
    entities.erase(ei);
    *ei = NULL;
    if ( e->is_beamable() || e->is_scannable() || (e->get_colgeom() && e->get_colgeom()->is_camera_collision()) )
      remove_cam_coll_ent( e );
  }

  ei_end = possible_active_ents.end();
  ei = find( possible_active_ents.begin(), ei_end, e );
  if ( ei != ei_end )
    *ei = NULL;

  ei_end = possible_render_ents.end();
  ei = find( possible_render_ents.begin(), ei_end, e );
  if ( ei != ei_end )
    *ei = NULL;

  ei_end = possible_collide_ents.end();
  ei = find( possible_collide_ents.begin(), ei_end, e );
  if ( ei != ei_end )
    *ei = NULL;
}
